svg.script:
let animate = false;
let animation_one = true;
const animation_time = 1000 * 15;

function zoom(){

  if(!animate){
    animate = true;
    const animation = animation_one ? "#anim1" : "#anim2";
    animation_one = !animation_one;

    const png = document.querySelector(animation);
    const static = document.querySelector("#static");

    png.style.display = "inline";
    static.style.display = "none";
    restart(png);

    setTimeout(() => {
      png.style.display = "none";
      static.style.display = "inline";
      animate = false;
    }, animation_time);
  }
}

function restart(png) {
  const parent = png.parentNode;
  parent.removeChild(png);
  parent.appendChild(png);
}
